import{_ as n,o as s,c as a,a2 as t}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Conversation Memory","description":"","frontmatter":{},"headers":[],"relativePath":"guide/conversations.md","filePath":"guide/conversations.md","lastUpdated":1793351152000}'),o={name:"guide/conversations.md"};function r(l,e,i,c,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="conversation-memory" tabindex="-1">Conversation Memory <a class="header-anchor" href="#conversation-memory" aria-label="Permalink to &quot;Conversation Memory&quot;">​</a></h1><p>Conversation memory gives an opted-in agent recent text and explicitly saved notes from the same chat across runs. It needs no embeddings or external search service. It is separate from a run&#39;s checkpoints and from agent-wide <a href="/guide/state">state</a>.</p><h2 id="enable-it-explicitly" tabindex="-1">Enable it explicitly <a class="header-anchor" href="#enable-it-explicitly" aria-label="Permalink to &quot;Enable it explicitly&quot;">​</a></h2><p>Enable both the app capability and <code>conversation: true</code> on the agent. A required <code>authorize</code> function decides whether the authenticated caller may dispatch to, recall from, or manage notes in that identity. Supply your own channel adapter and policy to this example:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> reply = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Send an answer to this conversation.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ text: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ text }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> context.channels.findOneOrFail(chat.name).emit({ body: text }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> helper = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;helper&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    conversation: { key: </span><span style="color:#E7C58C;">&#39;helper&#39;</span><span style="color:#E6DFDE;"> }, </span><span style="color:#958A8B;">// keep this key when renaming the agent</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Help the user. Send answers with reply. Save notes only when explicitly asked.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">        channel: chat.name,</span></span>
<span class="line"><span style="color:#E6DFDE;">        id: </span><span style="color:#E7C58C;">&#39;message&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        options: {},</span></span>
<span class="line"><span style="color:#E6DFDE;">    }],</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: (ctx) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({ reply, ...(hasConversation(ctx) ? memoryTools() : {}) }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">return</span><span style="color:#E6DFDE;"> createApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [helper],</span></span>
<span class="line"><span style="color:#E6DFDE;">    conversations: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        authorize, </span><span style="color:#958A8B;">// your policy checks authenticated identities for dispatch, recall and notes</span></span>
<span class="line"><span style="color:#E6DFDE;">        limits: {</span></span>
<span class="line"><span style="color:#E6DFDE;">            maxItems: </span><span style="color:#E7C58C;">20</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            maxHistoryBytes: </span><span style="color:#E7C58C;">32768</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            maxNotesBytes: </span><span style="color:#E7C58C;">8192</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">    modules: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">        name: </span><span style="color:#E7C58C;">&#39;example:chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> setup(container) { container.registerMany(AppToken.CHANNELS, { useValue: chat }); },</span></span>
<span class="line"><span style="color:#E6DFDE;">    }],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>memoryTools()</code> supplies <code>memory_list</code>, <code>memory_get</code>, <code>memory_set</code> and <code>memory_remove</code>. Add them through the tools factory when <code>hasConversation(ctx)</code> is true. They are not automatically installed. Ordinary runs of the same agent still work without a conversation binding. Executing a memory tool outside a bound run fails validation.</p><p>Without <code>conversations</code>, the app creates no conversation store. Enabling the agent without the app capability is a configuration error. The default conversation store uses the same selected PostgreSQL DataSource as the run store. With no selected DataSource it uses <code>MemoryConversationRepository</code> and warns: a process restart loses history and notes, and replicas do not share them. PostgreSQL is required for the default restart-durable production setup.</p><h2 id="keep-memory-when-renaming-an-agent" tabindex="-1">Keep memory when renaming an agent <a class="header-anchor" href="#keep-memory-when-renaming-an-agent" aria-label="Permalink to &quot;Keep memory when renaming an agent&quot;">​</a></h2><p>Use <code>conversation: { key: &#39;support&#39; }</code> to give memory a stable identifier. Keep the same key when changing <code>name</code>. To retain history first created with <code>conversation: true</code>, use the previous agent name as the key. Channel, account, chat and audience must still match. A different key starts separate history; it does not copy or migrate the old history. Before renaming an agent or changing its key, finish or explicitly cancel its queued, waiting and interrupted runs. The stable key preserves memory; existing runs retain their original agent name and are not reassigned. Queued runs bound to a changed key fail safely.</p><p>The authorizer receives <code>access.agent</code> as the actual agent name and <code>access.identity.agent</code> as the memory key. Check permissions using the actual agent and authenticated caller. Choosing a key grants no access by itself. Operator identity arguments also use the memory key in their <code>agent</code> field. Deliberately giving multiple agents the same key shares their memory under the policy you provide.</p><h2 id="trusted-intake-and-two-messages" tabindex="-1">Trusted intake and two messages <a class="header-anchor" href="#trusted-intake-and-two-messages" aria-label="Permalink to &quot;Trusted intake and two messages&quot;">​</a></h2><p>A channel adapter must authenticate and normalize the incoming event before calling <code>dispatchConversation</code>. Scope is the exact tuple of memory key, channel, account alias, chat and explicit audience. The memory key defaults to the agent name. The engine derives its concurrency key; omit <code>concurrencyKey</code> unless it matches that canonical key. Use the adapter&#39;s stable event ID as the idempotency key. Within the existing idempotency reservation lifetime, duplicate delivery remains a duplicate after reset when its original run exists. A rare failed run creation can leave an idempotency reservation without a run. Generation-zero retries can heal it. After any reset or deletion, the engine cannot prove that reservation&#39;s original generation and refuses to heal it into current memory. It requires explicit operator recovery or reservation expiry; retrying the same event does not automatically recover it.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> async</span><span style="color:#FF7B84;"> function</span><span style="color:#E6DFDE;"> firstMessage(engine: Engine, chat: IChannel) {</span></span>
<span class="line"><span style="color:#958A8B;">    // \`chat\` must be the exact registered adapter. Its authenticated event supplies these fields.</span></span>
<span class="line"><span style="color:#FF7B84;">    const</span><span style="color:#E6DFDE;"> text = </span><span style="color:#E7C58C;">&#39;Please remember that I prefer short answers.&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.channelContext(chat).dispatchConversation({</span></span>
<span class="line"><span style="color:#E6DFDE;">        agent: </span><span style="color:#E7C58C;">&#39;helper&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        trigger: </span><span style="color:#E7C58C;">&#39;message&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        address: </span><span style="color:#E7C58C;">&#39;example-chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        payload: { text },</span></span>
<span class="line"><span style="color:#E6DFDE;">        idempotencyKey: </span><span style="color:#E7C58C;">&#39;example-event-1&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    }, {</span></span>
<span class="line"><span style="color:#E6DFDE;">        account: </span><span style="color:#E7C58C;">&#39;main&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        chat: </span><span style="color:#E7C58C;">&#39;example-chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        audience: </span><span style="color:#E7C58C;">&#39;direct&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        text,</span></span>
<span class="line"><span style="color:#E6DFDE;">    });</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.idle();</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> async</span><span style="color:#FF7B84;"> function</span><span style="color:#E6DFDE;"> nextMessage(engine: Engine, chat: IChannel) {</span></span>
<span class="line"><span style="color:#958A8B;">    // After a restart, use the new engine and its exact registered adapter, with the same database.</span></span>
<span class="line"><span style="color:#FF7B84;">    const</span><span style="color:#E6DFDE;"> text = </span><span style="color:#E7C58C;">&#39;What answer style do I prefer?&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.channelContext(chat).dispatchConversation({</span></span>
<span class="line"><span style="color:#E6DFDE;">        agent: </span><span style="color:#E7C58C;">&#39;helper&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        trigger: </span><span style="color:#E7C58C;">&#39;message&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        address: </span><span style="color:#E7C58C;">&#39;example-chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        payload: { text },</span></span>
<span class="line"><span style="color:#E6DFDE;">        idempotencyKey: </span><span style="color:#E7C58C;">&#39;example-event-2&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    }, {</span></span>
<span class="line"><span style="color:#E6DFDE;">        account: </span><span style="color:#E7C58C;">&#39;main&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        chat: </span><span style="color:#E7C58C;">&#39;example-chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        audience: </span><span style="color:#E7C58C;">&#39;direct&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        text,</span></span>
<span class="line"><span style="color:#E6DFDE;">    });</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.idle();</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><p>Call <code>firstMessage</code> on a started engine. Stop the app normally, then start a new instance using the same PostgreSQL database and registered channel configuration. Call <code>nextMessage</code> on that new engine. Accepted prior input and confirmed replies are available as recent context; a <code>memory_set</code> note also survives the restart. The model chooses whether to call a tool, so explicit instructions and tool permissions still matter.</p><p>Use the exact registered channel object with <code>engine.channelContext(chat)</code>. Channel names supplied by arbitrary callers do not grant this capability. Bound runs send the accepted <code>text</code> as the current user message, with their attachments. The original event payload remains available to tools and audit records. The adapter supplies accepted plain text explicitly; raw Chat SDK payloads or HTTP request bodies are not trusted identities. Ordinary <code>engine.dispatch()</code> and handoffs discard forged conversation bindings. Built-in HTTP intake does not enable conversation recall by accepting account/chat fields.</p><p>For a private chat, the policy should check the authenticated caller&#39;s access to the account and chat. For a group, choose an audience that represents the actual authorized membership or view, and recheck it when membership changes. Do not reuse a private audience for a group or infer authorization from a concurrency key. The policy runs before admission and again for recall/resume and memory-tool calls. A later denial cannot retract content already sent to providers or tools.</p><h2 id="what-is-remembered" tabindex="-1">What is remembered <a class="header-anchor" href="#what-is-remembered" aria-label="Permalink to &quot;What is remembered&quot;">​</a></h2><p>Only accepted user text and ordinary messages emitted to the source channel and exact source address enter recent context. Emit with a tool such as <code>reply</code> above: returning final model text alone does not send or capture a reply. Approval notifications, other destinations, reasoning, tool results and attachments are not recalled as transcript messages.</p><p>A sent reply means <code>channel.out</code> resolved, not that a recipient read or received it. The journal records pending sends before calling the transport. If a crash leaves delivery uncertain, the item remains pending until reconciliation can mark it sent or unknown. Pending and unknown replies remain inspectable and stay out of future recall. External delivery still has an at-least-once crash window; use transport idempotency keys. On cancellation, an adapter that ignores its abort signal may still deliver late, but that late completion cannot write a successful framework receipt. An interrupted turn retains ownership for recovery, with the send pending until reconciliation.</p><p>Each run gets an immutable snapshot before its first model step. A resumed run keeps that snapshot. Notes appear as labeled untrusted user data before the selected transcript, never as system instructions. The current input remains last. There is no automatic memory extraction, summarization, semantic retrieval or transport-history backfill.</p><h2 id="limits-and-retention" tabindex="-1">Limits and retention <a class="header-anchor" href="#limits-and-retention" aria-label="Permalink to &quot;Limits and retention&quot;">​</a></h2><p><code>maxItems</code> and <code>maxStoredItems</code> count items; <code>retentionMs</code> counts milliseconds. The byte limits (<code>maxHistoryBytes</code>, <code>maxNotesBytes</code> and <code>maxItemBytes</code>) count UTF-8 bytes, not tokens. These limits do not guarantee that a model context window can fit the selected input. Selection keeps whole records, chooses recent records first and renders them chronologically; oversized records can be omitted, with an omission count in the snapshot.</p><table tabindex="0"><thead><tr><th>Limit</th><th style="text-align:right;">Default</th><th style="text-align:right;">Maximum</th></tr></thead><tbody><tr><td>Prior transcript items</td><td style="text-align:right;">20</td><td style="text-align:right;">100</td></tr><tr><td>Prior transcript bytes</td><td style="text-align:right;">32,768</td><td style="text-align:right;">131,072</td></tr><tr><td>Note context bytes</td><td style="text-align:right;">8,192</td><td style="text-align:right;">32,768</td></tr><tr><td>One accepted item, bytes</td><td style="text-align:right;">16,384</td><td style="text-align:right;">65,536</td></tr><tr><td>Transcript retention</td><td style="text-align:right;">30 days</td><td style="text-align:right;">365 days</td></tr><tr><td>Stored items per generation</td><td style="text-align:right;">1,000</td><td style="text-align:right;">10,000</td></tr></tbody></table><p><code>maxStoredItems</code> is enforced during admission and explicit pruning. Active turn records remain protected; a large settled turn can remain above this cap until the next admission or prune. Recall has its own item and byte bounds.</p><p>Configured limits must be positive integers. A note key holds 1–128 code units without controls; a note body holds at most 2,048 UTF-8 bytes. At most 100 live notes exist per scope; list requests return at most 50. Notes persist until removed unless given an expiry. Set/remove return metadata, and replay records retain no note body.</p><p>Expired notes disappear from reads; a new turn trims expired history. Explicit <code>engine.pruneConversations()</code> removes inactive retained data and settled note-operation replay records. The app adds no retention timer: arrange explicit pruning in your operator job. Active/recoverable replay records stay protected, and a settlement lookup failure retains records and surfaces the error.</p><h2 id="operator-management-and-deletion" tabindex="-1">Operator management and deletion <a class="header-anchor" href="#operator-management-and-deletion" aria-label="Permalink to &quot;Operator management and deletion&quot;">​</a></h2><p>These in-process APIs require possession of the engine. They are not model tools or public HTTP/UI routes:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> identity = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;helper&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channel: chat.name,</span></span>
<span class="line"><span style="color:#E6DFDE;">    account: </span><span style="color:#E7C58C;">&#39;main&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    chat: </span><span style="color:#E7C58C;">&#39;example-chat&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    audience: </span><span style="color:#E7C58C;">&#39;direct&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> inspection = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.inspectConversation(identity, { limit: </span><span style="color:#E7C58C;">20</span><span style="color:#E6DFDE;">, offset: </span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.resetConversation(identity, { keepNotes: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.deleteConversation(identity);</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.pruneConversations();</span></span></code></pre></div><p>Inspection of an unknown identity returns <code>undefined</code> and creates nothing. Reset advances the generation, invalidates queued old work and optionally keeps notes; it retains old transcript data until retention. Delete removes conversation-owned items, notes and operation records, and clears its active snapshot while retaining a generation tombstone that prevents stale work from restoring them. Both refuse an active turn; terminal owner reconciliation must finish first.</p><p>Deletion is not erasure of every copy. Runs retain trigger/payload and conversation input, and checkpoints, effects, provider logs and backups have their own lifecycles. Removing a note clears its live body, but prior immutable snapshots and audit copies can still contain it.</p><h2 id="repository-and-shutdown-lifecycle" tabindex="-1">Repository and shutdown lifecycle <a class="header-anchor" href="#repository-and-shutdown-lifecycle" aria-label="Permalink to &quot;Repository and shutdown lifecycle&quot;">​</a></h2><p>Normal app migrations install conversation tables even when recall is disabled. <code>chamvi start --check</code> validates configuration and connects read-only: it creates no conversation identity and runs no migrations. Existing migration flags keep their ordinary behavior.</p><p>Conversation policy lives in <code>conversations: { authorize, limits? }</code>; storage lives in <code>store.conversations</code>. For an app, pass custom capabilities through <code>storeModule({ store })</code>, or register the aggregate as <code>AppToken.STORE</code> in a replacement store module. Repository adapters reuse <code>@chamvi/core/conversation/persistence</code> for canonical identity validation, hashing and recall selection. A custom store owns its schema, connection and shutdown lifecycle. All built-in TypeORM roles, including conversations, must use the same DataSource; mixing the relational conversation store with another backend is unsupported. With the built-in store module, an injected DataSource remains caller-owned.</p><p>The existing app drain waits for engine executions and conversation journal/reconciliation writes before closing its owned DataSource. With the built-in PostgreSQL store, run and conversation records must share the same database. Their foreign keys enforce this relationship. Admission and conversation writes still use separate transactions; no cross-transaction atomicity is promised. Runs are created before conversation ownership is claimed, and restart reconciliation repairs terminal ownership safely.</p><h2 id="postgresql-records" tabindex="-1">PostgreSQL records <a class="header-anchor" href="#postgresql-records" aria-label="Permalink to &quot;PostgreSQL records&quot;">​</a></h2><p>Fixed fields use ordinary columns. Conversation-owned records reference their parent conversation with foreign keys. Only the frozen AI SDK messages need JSONB. The active snapshot lives on its conversation row and is cleared atomically when the turn ends.</p><table tabindex="0"><thead><tr><th>Record</th><th>Purpose</th></tr></thead><tbody><tr><td>Conversation</td><td>Identity, reset generation, current turn owner and its frozen context</td></tr><tr><td>Item</td><td>Accepted input or a reply with its delivery status</td></tr><tr><td>Note</td><td>Current explicitly saved text</td></tr><tr><td>Note operation</td><td>Metadata receipt committed atomically with a note edit, preventing duplicate edits on retry</td></tr></tbody></table><p>The active snapshot exists before a checkpoint can be written. Waiting and interrupted runs retain it; terminal settlement clears it. An ended run cannot request historical snapshot replay. The note receipt must commit in the same transaction as its edit. Existing checkpoints are written after model steps, and generic effects are not committed atomically with note edits. Run and checkpoint bindings retain scalar scope provenance with foreign keys to the local conversation row. The checkpoint&#39;s existing run ID identifies its source run; no duplicate snapshot run ID is stored.</p>`,39)])])}const m=n(o,[["render",r]]);export{y as __pageData,m as default};
